/*! nav v1.0.0 - Unlicensed - inspired by turbolinks and instant.page */

// Soft navigation: clicking a same-origin link fetches the page and
// swaps the whole document through xhtml, with pushState keeping the
// URL honest. Hovering (or touching) a link starts the fetch early, so
// the page is usually in hand by the time the click lands.

// Everything else falls back to a native navigation: modified clicks,
// external links, downloads, targets, non-HTML responses, network
// errors, and links opting out with data-native. Back and forward
// refetch through the same path.

var nav = window.nav || (() => {
  // How long a preloaded page may be served after fetching it. A click
  // usually follows its hover within a second or two; anything older is
  // refetched so listings do not go stale.
  const TTL = 10000;
  const preloads = new Map();

  let current = location.pathname + location.search;

  const eligible = (a) =>
    a && a.href && a.origin == location.origin &&
    !a.target && !a.hasAttribute("download") && !("native" in a.dataset) &&
    !(a.hash && a.pathname + a.search == location.pathname + location.search);

  const request = (url) =>
    fetch(url, { headers: { Accept: "text/html" } })
      .then(async (response) => ({ response, html: await response.text() }));

  const preload = (url) => {
    const hit = preloads.get(url);
    if(hit && performance.now() - hit.time < TTL) return hit.promise;

    const promise = request(url);
    preloads.set(url, { promise, time: performance.now() });
    promise.catch(() => preloads.delete(url));
    return promise;
  };

  // Renders a fetched page. History moves first, so scripts running
  // during the swap already see the destination URL.
  const render = (response, html, push = true) => {
    if(push && response.url != location.href) history.pushState(null, "", response.url);
    current = location.pathname + location.search;

    xhtml.swap(document.documentElement, html);
    if(push) scrollTo(0, 0);
  };

  const navigate = async (url, push = true) => {
    let exchange;
    try { exchange = await preload(url); }
    catch { location.href = url; return; }
    preloads.delete(url);

    const { response, html } = exchange;
    const type = response.headers.get("Content-Type") || "";

    // Anything unusual (errors, files) goes through the browser.
    if(!response.ok || !type.includes("text/html")) { location.href = url; return; }

    render(response, html, push);
  };

  const preload_target = (e) => {
    const a = e.target.closest?.("a[href]");
    if(eligible(a)) preload(a.href);
  };

  document.addEventListener("mouseover", preload_target, { passive: true });
  document.addEventListener("touchstart", preload_target, { passive: true });

  document.addEventListener("click", (e) => {
    if(e.defaultPrevented || e.button != 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;

    const a = e.target.closest?.("a[href]");
    if(!eligible(a)) return;

    e.preventDefault();
    navigate(a.href);
  });

  // A hash-only move is left entirely to the browser.
  addEventListener("popstate", () => {
    if(location.pathname + location.search == current) return;
    navigate(location.href, false);
  });

  return { navigate, render };
})();
